152	// writeCacheFile marshals v and writes it atomically (tmp + rename).
153	func writeCacheFile[T any](path string, v T) error {
154		data, err := json.MarshalIndent(v, "", "  ")
155		if err != nil {
156			return fmt.Errorf("marshal cache: %w", err)
157		}
158		return writeCacheBytesAtomic(path, data)
159	}
