162	// missing file is (nil, false, nil); other read errors propagate.
163	func readCacheBytes(path string) ([]byte, bool, error) {
164		data, err := os.ReadFile(path) // #nosec G304
165		if err != nil {
166			if os.IsNotExist(err) {
167				return nil, false, nil
168			}
169			return nil, false, fmt.Errorf("read cache: %w", err)
170		}
171		return data, true, nil
172	}
173	
174	// writeCacheBytesAtomic writes data via a tmp file + rename so a reader never
175	// observes a half-written cache.
176	func writeCacheBytesAtomic(path string, data []byte) error {
177		tmp := path + ".tmp"
178		if err := os.WriteFile(tmp, data, 0600); err != nil {
179			return fmt.Errorf("write cache tmp: %w", err)
180		}
181		if err := os.Rename(tmp, path); err != nil {
182			os.Remove(tmp) //nolint:gosec // cleanup best-effort
