// AudienceShape classifies an aud URL into the surface it addresses, so
// data-plane routes don't repeat the same prefix string match.
type AudienceShape struct {
	// Kind is the surface this aud names.
	Kind AudienceKind
	// Host is the URL hostname (no port). Empty when the aud isn't a valid
	// absolute URL.
	Host string
	// RepoSlug is the audience's URL path for AudienceRepo, including the
	// leading "/git/" prefix so it matches the `repo_urls.url` column
	// verbatim (today: "/et/<project>/<repo>"; "/git/repo/<ulid>" for
	// service-driven flows; whatever the URL layout becomes tomorrow —
	// repo_urls keys on the URL string and stays opaque to the shape).
	// The verifier compares this verbatim against the request route's
	// path; structural parsing of the slug lives in the data plane, not
	// here.
	RepoSlug string
}

// AudienceKind enumerates the surfaces a token's aud can name.
type AudienceKind int

const (
	// AudienceUnknown is the zero value: aud is empty or not a parseable URL.
	AudienceUnknown AudienceKind = iota
	// AudienceJurisdiction names entire-core's own surface (login,
	// api-access, sa-session tokens).
	AudienceJurisdiction
	// AudienceRepo names one native repo on one entiredb cluster.
	// Path begins with /git/ and resolves through repo_urls (global).
	AudienceRepo
	// AudienceMirror names one GitHub-mirror repo on one entiredb
	// cluster. Path begins with /gh/ and resolves through
	// github_mirror_repo_urls (per-cluster). Authz is GitHub-permission
	// based, not SpiceDB.
	AudienceMirror
	// AudienceAdmin names an entiredb cluster's admin surface.
	AudienceAdmin
	// AudienceDebug names an entiredb cluster's /debug/* surface.
	AudienceDebug
	// AudienceDeploy names an entiredb cluster's deploy-orchestration
	// RPC surface (stepdown / cancel-stepdown / pre-flight / status).
	AudienceDeploy
	// AudienceServiceEntiredb names the data plane as a logical
	// service rather than a specific cluster URL. Carried by tokens
	// addressed to entiredb's :8281 RepoAdmin RPCs (issued by
	// entire-core via client_credentials or token-exchange) and by
	// the legacy backup-access carve-out. The audience value is the
	// opaque URI EntiredbAudience ("service:entiredb"); the surface
	// is disambiguated downstream by scope and token_use.
	AudienceServiceEntiredb
)

// ClassifyAudience parses an aud URI and returns its shape. A non-URL or
// path that doesn't match any known surface returns AudienceUnknown.
func ClassifyAudience(aud string) AudienceShape {
	// service:entiredb is an opaque URI (scheme + opaque, no host) so it
	// short-circuits the URL parse below. Treated as a kind in its own
	// right; receivers (entiredb's :8281 RepoAdmin mount) match on the
	// audience kind, not the URL parts.
	if aud == EntiredbAudience {
		return AudienceShape{Kind: AudienceServiceEntiredb}
	}
	u, err := url.Parse(aud)
	if err != nil || u.Scheme == "" || u.Host == "" {
		return AudienceShape{Kind: AudienceUnknown}
	}
	shape := AudienceShape{Host: u.Hostname()}
	switch {
	case u.Path == "":
		shape.Kind = AudienceJurisdiction
	case strings.HasPrefix(u.Path, AudiencePathMirrorRepoPrefix):
		// Any path under /gh/ is a mirror-repo audience. RepoSlug
		// carries the full path including /gh/ so it matches
		// `github_mirror_repo_urls.url` verbatim. Distinct from /git/
		// because the resolver and the authz check are both different.
		shape.Kind = AudienceMirror
		shape.RepoSlug = u.Path
	case IsRepoAudienceSlug(u.Path):
		// Any path under /et/ (or the legacy /git/) is a repo audience.
		// The slug stays as the full path including the prefix so it
		// matches `repo_urls.url` verbatim — receiver-side lookups don't
		// have to know the prefix convention. The slug after the prefix
		// is opaque: could be "repo/<ulid>" (service-driven flows),
		// "<project>/<repo>" (user-facing layout), or anything else
		// repo_urls chooses tomorrow.
		shape.Kind = AudienceRepo
		shape.RepoSlug = u.Path
	case u.Path == AudiencePathAdmin:
		shape.Kind = AudienceAdmin
	case u.Path == AudiencePathDebug:
		shape.Kind = AudienceDebug
	case u.Path == AudiencePathDeploy:
		shape.Kind = AudienceDeploy
	default:
		shape.Kind = AudienceUnknown
	}
	return shape
}

// IsRepoAudienceSlug reports whether slug names a native-repo audience —
// it begins with the current /et/ prefix or the legacy /git/ prefix.
// Use to admit both at boundaries (audience verification, slug parsing,
// repo_urls lookups) so existing /git/-stamped rows keep resolving while
// new repos get stamped under /et/.
func IsRepoAudienceSlug(slug string) bool {
	return strings.HasPrefix(slug, AudiencePathRepoPrefix) ||
		strings.HasPrefix(slug, LegacyAudiencePathRepoPrefix)
}

// originURI returns scheme://host for the given URL string. label appears in
// error messages so callers can attribute a malformed input back to its
// config source.
func originURI(s, label string) (string, error) {
	if s == "" {
		return "", fmt.Errorf("%s is empty", label)
	}
	u, err := url.Parse(strings.TrimRight(s, "/"))
	if err != nil {
		return "", fmt.Errorf("parse %s: %w", label, err)
	}
	if u.Scheme == "" || u.Host == "" {
		return "", fmt.Errorf("%s missing scheme/host: %q", label, s)
	}
	return u.Scheme + "://" + u.Host, nil
}
