// resolveCoreTokenEndpoint picks where to redeem the auth code. When the
// callback carries an RFC 9207 `iss` (cross-region foreign-region forward),
// we send the redemption to that issuer — but only if it's in the operator-
// configured allowlist; otherwise we'd be handing client_secret to whoever
// crafted the callback URL. The configured ENTIRE_CORE_BASE_URL is
// implicitly trusted (same-region default). Returns the trusted base, or
// undefined if `iss` was supplied but not allowed.
function resolveCoreTokenEndpoint(
  env: Env,
  config: CoreAuthConfig,
  iss: string | undefined,
): string | undefined {
  if (!iss) {
    return config.baseUrl
  }
  const candidate = iss.replace(/\/+$/, "")
  if (candidate === config.baseUrl) {
    return config.baseUrl
  }
  const allowlist = (env.ENTIRE_CORE_TRUSTED_ISSUERS ?? "")
    .split(",")
    .map((s) => s.trim().replace(/\/+$/, ""))
    .filter((s) => s !== "")
  if (allowlist.includes(candidate)) {
    return candidate
  }
  return undefined
}

function parseCoreOAuthStateContext(storedContext: string): CoreOAuthStateContext | undefined {
  try {
    const context = JSON.parse(storedContext) as unknown
    if (!context || typeof context !== "object" || Array.isArray(context)) {
