export interface CoreBearerEnv {
  ENTIRE_CORE_BEARER_ENABLED?: string
  ENTIRE_CORE_BASE_URL?: string
  ENTIRE_CORE_JWT_AUDIENCE?: string
}

// APIDiscoveryEnv is the config the /.well-known/entire-api.json document is
// sourced from. ENTIRE_CORE_TRUSTED_ISSUERS is the same comma-separated
// allowlist auth.ts reads for the RFC 9207 callback; the base URL is always
// implicitly trusted in addition to it.
export interface APIDiscoveryEnv extends CoreBearerEnv {
  ENTIRE_CORE_TRUSTED_ISSUERS?: string
}

// APIDiscoveryDoc is the body of /.well-known/entire-api.json. It tells a CLI
// holding only the data-API host (e.g. ENTIRE_API_BASE_URL=https://partial.to)
// which login server(s) this resource server trusts and which audience the CLI
// must exchange its core token for — so it can pick the matching auth context
// without the operator also setting ENTIRE_AUTH_BASE_URL. Mirrors the cluster
// blob (entiredb server/cluster_discovery.go) but adds `audience`, since unlike
// a git cluster the data API validates a fixed `aud` claim.
export interface APIDiscoveryDoc {
  // issuer is this API's home core — ENTIRE_CORE_BASE_URL.
  issuer: string
  // trusted_issuers is every core whose JWTs this API accepts: the issuer plus
  // ENTIRE_CORE_TRUSTED_ISSUERS, deduplicated and sorted.
  trusted_issuers: string[]
  // audience is the `aud` the exchanged token must carry — ENTIRE_CORE_JWT_AUDIENCE.
  audience: string
  // jwks_uri is where the issuer publishes its signing keys.
  jwks_uri: string
}

// buildAPIDiscoveryDoc assembles the /.well-known/entire-api.json body from the
// same env the bearer validator already trusts. Returns null when the required
// config is absent or the base URL isn't an acceptable (https / loopback) JWKS
// origin, so the route can answer 503 rather than advertise a half-configured
// trust root. Independent of ENTIRE_CORE_BEARER_ENABLED: the document only
// describes trust roots and is safe (and useful) to publish even while inbound
// core-JWT acceptance is still being rolled out per environment.
export function buildAPIDiscoveryDoc(env: APIDiscoveryEnv): APIDiscoveryDoc | null {
  if (!env.ENTIRE_CORE_BASE_URL || !env.ENTIRE_CORE_JWT_AUDIENCE) {
    return null
  }
  const issuer = normalizeBaseUrl(env.ENTIRE_CORE_BASE_URL)
  if (!issuer || !isAcceptableJwksOrigin(issuer)) {
    return null
  }
  const extra = (env.ENTIRE_CORE_TRUSTED_ISSUERS ?? "")
    .split(",")
    .map((s) => s.trim().replace(/\/+$/, ""))
    .filter((s) => s !== "")
  const trustedIssuers = Array.from(new Set([issuer, ...extra])).sort()
  return {
    issuer,
    trusted_issuers: trustedIssuers,
    audience: env.ENTIRE_CORE_JWT_AUDIENCE,
    jwks_uri: `${issuer}/.well-known/jwks.json`,
  }
}

