describe("buildAPIDiscoveryDoc", () => {
  const ok: APIDiscoveryEnv = {
    ENTIRE_CORE_BASE_URL: ISSUER,
    ENTIRE_CORE_JWT_AUDIENCE: AUDIENCE,
    ENTIRE_CORE_TRUSTED_ISSUERS: "https://us.auth.test,https://eu.auth.test",
  }

  it("assembles the document, merging the issuer into trusted_issuers", () => {
    expect(buildAPIDiscoveryDoc(ok)).toEqual({
      issuer: ISSUER,
      trusted_issuers: ["https://core.test", "https://eu.auth.test", "https://us.auth.test"],
      audience: AUDIENCE,
      jwks_uri: `${ISSUER}/.well-known/jwks.json`,
    })
  })

  it("does not require ENTIRE_CORE_BEARER_ENABLED", () => {
    const doc = buildAPIDiscoveryDoc({ ...ok, ENTIRE_CORE_BEARER_ENABLED: "false" })
    expect(doc?.issuer).toBe(ISSUER)
  })

  it("defaults trusted_issuers to just the issuer when none are configured", () => {
    expect(buildAPIDiscoveryDoc({ ...ok, ENTIRE_CORE_TRUSTED_ISSUERS: undefined })).toEqual({
      issuer: ISSUER,
      trusted_issuers: [ISSUER],
      audience: AUDIENCE,
      jwks_uri: `${ISSUER}/.well-known/jwks.json`,
    })
  })

  it("normalizes a trailing slash on the issuer and dedupes it from the list", () => {
    const doc = buildAPIDiscoveryDoc({
      ...ok,
      ENTIRE_CORE_BASE_URL: `${ISSUER}/`,
      ENTIRE_CORE_TRUSTED_ISSUERS: `${ISSUER}/, https://eu.auth.test/`,
    })
    expect(doc?.issuer).toBe(ISSUER)
    expect(doc?.trusted_issuers).toEqual([ISSUER, "https://eu.auth.test"])
  })

  it("returns null when the base URL is missing", () => {
    expect(buildAPIDiscoveryDoc({ ...ok, ENTIRE_CORE_BASE_URL: undefined })).toBeNull()
  })

  it("returns null when the audience is missing", () => {
    expect(buildAPIDiscoveryDoc({ ...ok, ENTIRE_CORE_JWT_AUDIENCE: undefined })).toBeNull()
  })

  it("returns null for a non-loopback http base URL", () => {
    expect(buildAPIDiscoveryDoc({ ...ok, ENTIRE_CORE_BASE_URL: "http://core.example" })).toBeNull()
  })

  it("allows a loopback http base URL for local dev", () => {
    const doc = buildAPIDiscoveryDoc({ ...ok, ENTIRE_CORE_BASE_URL: "http://localhost:8080" })
    expect(doc?.issuer).toBe("http://localhost:8080")
    expect(doc?.jwks_uri).toBe("http://localhost:8080/.well-known/jwks.json")
  })
})

